'use strict';
// Category 7 — Breaker & Circuit Load
// Every tool ships a pure, self-contained `compute` function (also used by the
// test harness) and 2000+ words of unique, entity-rich content. Formulas follow
// the NEC 80% continuous-load rule and standard breaker sizes:
//   15, 20, 25, 30, 40, 50, 60, 70, 80, 90, 100, 125, 150, 175, 200 A.

/* ------------------------------------------------------------------ */
/* 1. BREAKER SIZE CALCULATOR                                          */
/* ------------------------------------------------------------------ */
const breakerSize = {
  slug: 'breaker-size-calculator',
  category: 'Breaker & Circuit Load',
  kicker: 'Breaker sizing',
  h1: 'Breaker Size Calculator',
  title: 'Breaker Size Calculator — What Size Breaker Do I Need | Ampstowatt',
  metaDesc: 'Find what size breaker you need from watts and voltage. Applies the NEC 80% continuous-load rule and rounds up to the next standard breaker size (15A–200A).',
  keywords: ['breaker size calculator', 'what size breaker do i need', 'motor breaker size calculator', 'circuit breaker sizing', 'nec breaker calculator'],
  formulaPill: 'Breaker = (Watts ÷ Volts ÷ 0.8) → next standard size',
  lead: 'Use this <strong>breaker size calculator</strong> to convert a watt load into the correct circuit breaker rating. It divides watts by voltage to get amps, applies the NEC 80% rule for continuous loads, then rounds up to the next standard breaker size so your circuit is code-compliant and safe.',
  reviewed: 'September 5, 2026',
  featureList: ['Watts-to-breaker sizing in amps', 'NEC 80% continuous-load rule built in', 'Rounds up to standard breaker sizes (15A–200A)', 'Continuous and non-continuous load modes'],
  methodology: 'The calculator converts the entered watt load to amps (amps = watts ÷ volts). For continuous loads it divides the load current by 0.80 per NEC 210.20(A) and 215.3, which require a breaker rated at no less than 125% of a continuous load. It then selects the next standard overcurrent device size from NEC 240.6(A): 15, 20, 25, 30, 40, 50, 60, 70, 80, 90, 100, 125, 150, 175, and 200 amps.',
  calc: {
    id: 'breaker-size',
    title: 'Breaker Size Calculator',
    subtitle: 'What size breaker do I need for this load?',
    primaryLabel: 'Recommended Breaker Size',
    primaryUnit: 'A',
    formulaText: 'Breaker = (Watts ÷ Volts ÷ 0.8) rounded up',
    note: 'Continuous loads use the 80% rule; result is the next standard breaker size.',
    secondary: [
      { label: 'Load Current', unit: 'A' },
      { label: 'Required Ampacity', unit: 'A' },
      { label: 'Headroom', unit: '%' },
    ],
    inputs: [
      { id: 'load', label: 'Load', unit: 'W', type: 'number', value: 3000, min: 0 },
      { id: 'voltage', label: 'Voltage', unit: 'V', type: 'select', value: '240', options: [{ v: '120', t: '120 V' }, { v: '240', t: '240 V' }, { v: '208', t: '208 V' }] },
      { id: 'type', label: 'Load Type', unit: '', type: 'select', value: 'continuous', options: [{ v: 'continuous', t: 'Continuous (3+ hrs)' }, { v: 'non-continuous', t: 'Non-continuous' }] },
    ],
    compute: function compute(v) {
      var volts = parseFloat(v.voltage);
      var amps = v.load / volts;
      var required = (v.type === 'non-continuous') ? amps : amps / 0.8;
      var sizes = [15, 20, 25, 30, 40, 50, 60, 70, 80, 90, 100, 125, 150, 175, 200];
      var breaker = sizes[sizes.length - 1];
      for (var i = 0; i < sizes.length; i++) { if (sizes[i] >= required) { breaker = sizes[i]; break; } }
      var headroom = breaker > 0 ? (1 - required / breaker) * 100 : 0;
      return {
        primary: { label: 'Recommended Breaker Size', value: breaker, unit: 'A', precision: 0 },
        secondary: [
          { label: 'Load Current', value: amps, unit: 'A', precision: 2 },
          { label: 'Required Ampacity', value: required, unit: 'A', precision: 2 },
          { label: 'Headroom', value: headroom, unit: '%', precision: 0 },
        ],
        formula: 'Breaker = ' + v.load + 'W ÷ ' + volts + 'V' + (v.type === 'non-continuous' ? '' : ' ÷ 0.8') + ' = ' + required.toFixed(2) + 'A → ' + breaker + 'A',
        note: v.type === 'non-continuous' ? 'Non-continuous: breaker sized to load current.' : 'Continuous load sized at 125% (÷ 0.8) per NEC.',
      };
    },
    tests: [
      { name: '3000W 240V continuous', in: { load: 3000, voltage: '240', type: 'continuous' }, expect: 20, tol: 0.01 },
      { name: '1500W 120V continuous', in: { load: 1500, voltage: '120', type: 'continuous' }, expect: 20, tol: 0.01 },
      { name: '2400W 240V non-continuous', in: { load: 2400, voltage: '240', type: 'non-continuous' }, expect: 15, tol: 0.01 },
    ],
  },
  content: [
    { type: 'section', id: 'quick-answer', icon: '⚡', heading: 'What Size Breaker Do I Need? Quick Answer', html: `<p class="content-p"><strong>To size a breaker, divide the load in watts by the circuit voltage to get amps, divide by 0.8 for continuous loads, then round up to the next standard breaker size.</strong> A 3,000-watt continuous load on a 240-volt circuit draws 12.5 amps. Dividing by 0.8 gives a required ampacity of 15.6 amps, so the next standard breaker is a <strong>20-amp breaker</strong>. The calculator above does this instantly and also shows load current, required ampacity, and the safety headroom left on the breaker.</p><p class="content-p">Circuit breakers are not sized to match the load exactly. The National Electrical Code (NEC) requires a continuous load — one expected to run for three hours or more — to be served by an overcurrent device rated at least 125% of that load. Because 125% is the same as dividing by 0.80, electricians call it the <strong>80% rule</strong>: a breaker should carry no more than 80% of its rating continuously. Sizing to this rule keeps the breaker cool, prevents nuisance tripping, and satisfies inspectors.</p>` },
    { type: 'section', id: 'formula', icon: 'f(x)', heading: 'The Breaker Sizing Formula Explained', html: `<p class="content-p">The equation this calculator uses has three steps:</p><div class="tool-guide-formula">Step 1: Amps = Watts ÷ Volts<br>Step 2: Required ampacity = Amps ÷ 0.8 (continuous only)<br>Step 3: Breaker = next standard size ≥ required ampacity</div><p class="content-p">Each step matters:</p><ul><li><strong>Watts ÷ Volts</strong> converts power into current. On single-phase circuits, use 120V for standard receptacles and lighting, 240V for large appliances, and 208V for many commercial single-phase circuits fed from a three-phase panel.</li><li><strong>Divide by 0.8</strong> only for continuous loads. This applies the NEC 125% factor. Non-continuous loads (running less than three hours, like a receptacle circuit) can be sized to the load current directly, though good practice still leaves margin.</li><li><strong>Round up to a standard size.</strong> Breakers are only manufactured in fixed ratings. NEC 240.6(A) lists the standard sizes; you must select the next size at or above the required ampacity, never a smaller one.</li></ul><p class="content-p">The conductor must also be rated for the breaker: a 20A breaker needs 12 AWG copper, a 30A breaker needs 10 AWG, and so on. Verify wire sizing with the <a href="/wire-size-calculator/">wire size calculator</a> before finalizing any circuit. For whole-panel planning, use the <a href="/electrical-load-calculator-for-house/">electrical load calculator for house</a>.</p>`, table: { caption: 'Standard breaker sizes per NEC 240.6(A) and typical uses', columns: ['Breaker', 'Max Continuous Load (80%)', 'Copper Wire', 'Common Circuits'], rows: [['15 A', '12 A', '14 AWG', 'Lighting, general receptacles'], ['20 A', '16 A', '12 AWG', 'Kitchen, bath, garage receptacles'], ['30 A', '24 A', '10 AWG', 'Dryer (240V), water heater, RV'], ['40 A', '32 A', '8 AWG', 'Electric range, EV charger'], ['50 A', '40 A', '6 AWG', 'Range, large EV charger, welder'], ['60 A', '48 A', '4 AWG', 'Subpanel feed, HVAC'], ['100 A', '80 A', '3–1 AWG', 'Subpanels, small services'], ['200 A', '160 A', '2/0–4/0 AWG', 'Main residential service']] } },
    { type: 'section', id: 'examples', icon: '#', heading: 'Worked Examples: Sizing Real Breakers', html: `<p class="content-p">These examples show the full three-step method with the arithmetic spelled out.</p><p class="content-p"><strong>Example 1 — 3,000W continuous heater on 240V:</strong> Amps = 3,000 ÷ 240 = 12.5 A. Continuous, so required = 12.5 ÷ 0.8 = 15.63 A. The next standard breaker above 15.63 is <strong>20 A</strong>. A 15A breaker would be undersized because 15.63 exceeds 15.</p><p class="content-p"><strong>Example 2 — 1,500W space heater on 120V:</strong> Amps = 1,500 ÷ 120 = 12.5 A. Continuous, so required = 12.5 ÷ 0.8 = 15.6 A → <strong>20 A</strong> breaker on 12 AWG wire. This is why space heaters are notorious for tripping shared 15A living-room circuits.</p><p class="content-p"><strong>Example 3 — 4,800W electric range element on 240V (non-continuous):</strong> Amps = 4,800 ÷ 240 = 20 A. Cooking is treated as non-continuous, so required ≈ 20 A → a <strong>25 A</strong> breaker would cover it, though ranges are usually on 40–50A circuits because of the combined nameplate demand of all burners plus the oven.</p><p class="content-p"><strong>Example 4 — 1 HP motor at 240V:</strong> A 1 HP single-phase motor has a full-load current near 8 A. Motor branch-circuit protection is sized higher — often 250% of full-load current for inrush — so a motor may legally sit on a 15–20A breaker even though its running current is only 8 A. Motors follow NEC Article 430 rather than the plain 80% rule, so treat this tool's motor output as a running-load starting point and confirm with the motor nameplate.</p>` },
    { type: 'section', id: 'continuous', icon: '⏱', heading: 'The 80% Rule: Continuous vs Non-Continuous Loads', html: `<p class="content-p">The single most misunderstood part of breaker sizing is the difference between continuous and non-continuous loads.</p><p class="content-p">A <strong>continuous load</strong> is any load expected to operate at its maximum current for <strong>three hours or more</strong>. Examples include electric water heaters, baseboard heat, EV chargers, commercial lighting, and HVAC. NEC 210.20(A) requires the breaker (and the conductor) to be rated at 125% of a continuous load — equivalently, the continuous load may not exceed 80% of the breaker rating. That is why a 20A breaker is limited to 16 continuous amps and a 30A breaker to 24 continuous amps.</p><p class="content-p">A <strong>non-continuous load</strong> runs in shorter bursts: kitchen appliances, power tools, receptacle circuits, and cooking equipment. These can be sized to the actual load current, though most electricians still leave headroom. When a circuit carries both continuous and non-continuous loads, the required breaker is <strong>125% of the continuous portion plus 100% of the non-continuous portion</strong>.</p><p class="content-p">Getting this wrong is a real hazard. A breaker loaded to 100% continuously runs hot, its thermal element ages, and it may either trip randomly (a nuisance) or fail to trip when it should. Sizing to 80% keeps everything within its thermal design margin.</p>`, table: { caption: 'Continuous-load capacity of common breakers (80% rule)', columns: ['Breaker Rating', 'Continuous Limit (× 0.8)', 'Watts @ 120V', 'Watts @ 240V'], rows: [['15 A', '12 A', '1,440 W', '2,880 W'], ['20 A', '16 A', '1,920 W', '3,840 W'], ['30 A', '24 A', '2,880 W', '5,760 W'], ['40 A', '32 A', '3,840 W', '7,680 W'], ['50 A', '40 A', '4,800 W', '9,600 W'], ['60 A', '48 A', '5,760 W', '11,520 W']] } },
    { type: 'section', id: 'how-to-use', icon: '✓', heading: 'How to Use the Breaker Size Calculator', html: `<ol><li><strong>Enter the load in watts.</strong> Use the nameplate wattage of the appliance or the total watts of everything on the circuit. If you only know amps, multiply amps × volts first.</li><li><strong>Select the voltage.</strong> Choose 120V for standard branch circuits, 240V for large appliances and dryers, or 208V for commercial single-phase circuits.</li><li><strong>Choose the load type.</strong> Select "Continuous" for anything that runs three hours or more (heaters, EV chargers, HVAC); select "Non-continuous" for intermittent loads.</li><li><strong>Read the recommended breaker size.</strong> The primary result is the next standard breaker at or above the required ampacity. The secondary outputs show your actual load current, the code-required ampacity, and the percentage of headroom remaining.</li></ol><p class="content-p">After sizing the breaker, confirm the conductor with the <a href="/wire-size-calculator/">wire size calculator</a> and check the total circuit demand with the <a href="/circuit-load-calculator/">circuit load calculator</a>.</p>` },
    { type: 'section', id: 'mistakes', icon: '!', heading: 'Common Breaker Sizing Mistakes', html: `<ul><li><strong>Ignoring the 80% rule.</strong> Loading a 20A breaker to a full 2,400W continuously (20A × 120V) will trip it. The real continuous limit is 1,920W.</li><li><strong>Upsizing the breaker without upsizing the wire.</strong> Putting a 30A breaker on 12 AWG wire is a fire hazard — the wire can overheat before the breaker trips. The breaker protects the conductor, so they must match.</li><li><strong>Rounding down.</strong> If the required ampacity is 15.6 A, you must go up to 20 A, not down to 15 A.</li><li><strong>Treating motors like resistive loads.</strong> Motors draw large inrush current and follow NEC Article 430, not the simple 80% rule. Use the <a href="/circuit-load-calculator/">circuit load calculator</a> for resistive loads and a motor-specific method for motors.</li><li><strong>Forgetting derating.</strong> Multiple conductors in a conduit or high ambient temperature reduce a wire's usable ampacity, which can force a larger conductor even when the breaker size looks fine.</li></ul>` },
    { type: 'section', id: 'why-standard', icon: '⚙', heading: 'Why Breakers Come in Standard Sizes', html: `<p class="content-p">A frequent surprise for people new to electrical work is that you cannot buy a breaker in any rating you like. NEC 240.6(A) publishes a fixed list of standard overcurrent-device sizes, and manufacturers build to that list: 15, 20, 25, 30, 40, 50, 60, 70, 80, 90, 100, 125, 150, 175, and 200 amps, with larger sizes continuing above. Notice the gaps — there is no 35A breaker, and the jump from 100A to 125A skips 110 and 115. Whenever your calculated required ampacity lands between two standard values, you must select the next size up, never the closer size down.</p><p class="content-p">This standardization exists for good reasons. Coordinating protection across a system — the main breaker, subpanel feeders, and branch circuits — is far simpler when everyone works from the same rung of sizes. It also lets conductor ampacity tables, tap rules, and equipment ratings align cleanly with breaker ratings. The trade-off is that circuits are almost always slightly oversized relative to the pure calculation, which is exactly the safety margin the code intends.</p><p class="content-p">There is one important exception built into the code. NEC 240.4(B) permits rounding <em>up</em> to the next standard breaker when a conductor's ampacity does not match a standard size — but only for circuits rated 800 amps or less, and only when the conductor is not part of a multi-outlet branch circuit supplying receptacles for portable, cord-and-plug loads. For ordinary receptacle circuits, NEC 240.4(D) instead sets hard ceilings: 14 AWG copper is capped at 15A, 12 AWG at 20A, and 10 AWG at 30A, regardless of the higher ampacities those wires show in the 60/75/90°C tables. These "small-conductor" rules are why a 12 AWG wire that can technically carry 25 or 30 amps is still limited to a 20A breaker on a normal branch circuit.</p><p class="content-p">Understanding this hierarchy — calculate the load, apply the continuous factor, round up to a standard size, then confirm the conductor is legal for that breaker — keeps every circuit both code-compliant and genuinely safe. When in doubt, size conservatively; the small extra cost of the next wire gauge is trivial next to the risk of an overheated conductor.</p>` },
    { type: 'section', id: 'applications', icon: '⌂', heading: 'Breaker Sizes for Common Household Loads', html: `<p class="content-p">Here are typical breaker sizes for common residential loads, useful as a sanity check against the calculator.</p><p class="content-p"><strong>Lighting and general receptacles</strong> sit on 15A or 20A circuits. <strong>Kitchen small-appliance</strong> circuits are 20A by code (at least two required). An <strong>electric dryer</strong> is usually a 30A/240V circuit on 10 AWG. An <strong>electric water heater</strong> (4,500W/240V) needs a 30A breaker — see the dedicated <a href="/what-size-breaker-for-water-heater/">water heater breaker calculator</a>. An <strong>electric range</strong> typically uses 40–50A. A <strong>Level 2 EV charger</strong> at 32A continuous needs a 40A breaker (32 ÷ 0.8 = 40).</p><p class="content-p">Central <strong>air conditioning and heat pumps</strong> list a "maximum overcurrent protection" (MOCP) value on the nameplate — always use that number rather than calculating from watts, because HVAC compressors have special inrush requirements. When adding several new circuits, verify the panel and service can carry the total with the <a href="/electrical-load-calculator-for-house/">electrical load calculator for house</a> so you do not overload the main breaker.</p>` },
  ],
  faq: [
    { q: 'What size breaker do I need for a 3,000-watt load?', a: 'On a 240V circuit, 3,000W draws 12.5 amps. For a continuous load you divide by 0.8 to get 15.6 amps, which rounds up to a <strong>20-amp breaker</strong>. On a 120V circuit the same 3,000W would draw 25 amps and need a 40-amp breaker, which is why high-wattage appliances use 240V.' },
    { q: 'What is the 80% rule for breakers?', a: 'The NEC requires a breaker to be rated at least 125% of a continuous load (one running three or more hours). Dividing by 0.8 is the same as multiplying by 1.25, so a breaker should carry no more than 80% of its rating continuously: 16A on a 20A breaker, 24A on a 30A breaker, and so on.' },
    { q: 'Can I put a bigger breaker on the same wire?', a: 'No. The breaker protects the wire, so its rating must not exceed the wire ampacity. 14 AWG is limited to a 15A breaker, 12 AWG to 20A, and 10 AWG to 30A. Installing a larger breaker on undersized wire lets the conductor overheat before the breaker trips — a fire risk.' },
    { q: 'How do I size a breaker for a motor?', a: 'Motors follow NEC Article 430, not the plain 80% rule. Branch-circuit protection is based on the motor full-load current times a factor (often up to 250% for inverse-time breakers) to allow starting inrush, while the overload device protects the running load. Use the motor nameplate full-load amps, not calculated watts.' },
    { q: 'What are the standard breaker sizes?', a: 'Per NEC 240.6(A), standard breaker ratings are 15, 20, 25, 30, 40, 50, 60, 70, 80, 90, 100, 125, 150, 175, and 200 amps (larger sizes exist too). Note there is no 35A standard size, so a load requiring more than 30A jumps to 40A.' },
    { q: 'What size breaker for a 120V vs 240V load?', a: 'At 240V a load draws half the current it would at 120V for the same wattage, so it needs a smaller breaker and thinner wire. A 4,800W load needs 40A at 120V but only 20A at 240V. This is why dryers, ranges, and EV chargers use 240V.' },
    { q: 'Does the calculator account for the wire size?', a: 'It sizes the breaker to the load. The conductor must be independently rated for that breaker — 20A needs 12 AWG copper, 30A needs 10 AWG, 40A needs 8 AWG, and so on. Always confirm the wire with the wire size calculator, and derate for conduit fill and temperature.' },
  ],
  related: [
    { href: '/wire-size-calculator/', badge: 'AWG', title: 'Wire Size Calculator', desc: 'Match conductor to breaker and load' },
    { href: '/circuit-load-calculator/', badge: 'A', title: 'Circuit Load Calculator', desc: 'Max watts and amps per breaker' },
    { href: '/electrical-load-calculator-for-house/', badge: 'kVA', title: 'House Electrical Load Calculator', desc: 'Size your service and panel' },
    { href: '/what-size-breaker-for-water-heater/', badge: '🔥', title: 'Water Heater Breaker Size', desc: 'Breaker and wire for water heaters' },
    { href: '/how-many-watts-on-a-20-amp-circuit/', badge: '20A', title: 'Watts on a 20 Amp Circuit', desc: 'Safe watt limits by voltage' },
    { href: '/watts-to-amps-calculator/', badge: 'A', title: 'Watts to Amps Calculator', desc: 'Convert power to current' },
  ],
};

